package net.spell_engine.internals;
import java.util.*;import net.minecraft.core.Holder;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.LivingEntity;import net.spell_engine.api.spell.Spell;
/** A recovery cue follows a real health increase, never a successful-but-empty heal. */
public final class ClassHealingVisuals{static final Set<String> RECOVERY=Set.of("skill_tree_rpgs:warrior_tier_2_passive_1","skill_tree_rpgs:rogue_tier_4_spell_2_modifier_1","skill_tree_rpgs:archer_tier_3_spell_1_modifier_2","skill_tree_rpgs:arcane_tier_1_passive_2");public static boolean heal(LivingEntity target,float amount,Holder<Spell> spell){float before=target.getHealth();target.heal(amount);if(target.getHealth()>before+.001&&RECOVERY.contains(spell.unwrapKey().map(k->k.identifier().toString()).orElse(""))&&!ClassStatusVisuals.concealed(target)&&target.level() instanceof ServerLevel world)world.sendParticles(net.minecraft.core.particles.ParticleTypes.HEART,target.getX(),target.getY()+1,target.getZ(),1,.2,.25,.2,.01);return target.getHealth()>before+.001;}public static net.spell_engine.api.spell.fx.Fx.Visuals visuals(net.spell_engine.api.spell.fx.Fx.Visuals original,boolean changed){return changed?original:new net.spell_engine.api.spell.fx.Fx.Visuals();}public static net.spell_engine.api.spell.fx.Sound sound(net.spell_engine.api.spell.fx.Sound original,boolean changed){return changed?original:null;}}
